-- Approved new customer.
update public.customers
set customer_code='294', is_active=true
where regexp_replace(trim(company_name), '[[:space:]]+', ' ', 'g')='مهندس جعفری';

-- Only the approved 12 no-code records remain inactive.
update public.customers
set is_active=false, customer_code=null
where regexp_replace(trim(company_name), '[[:space:]]+', ' ', 'g') in (
  'اقساط بانک ملت',
  'بانک پارسیان اصغر زنده بودی',
  'بانک پارسیان فاطمه زنده بودی',
  'بانک پارسیان گل شیرین زنده بودی',
  'دستگاه مورف 00',
  'سعید بوشهری سنگی زاده',
  'غلامرضا اسدی-کولر',
  'کلثوم زنده بودی-وام بانک ملی',
  'مبلمان شمس',
  'وام بانک ملی ابراهیم بچاچری',
  'وام علی زنده بودی بانک ملی',
  'وحید زنده بودی-هزینه حمل'
);

select setval('public.customer_code_seq', greatest(294, coalesce((select max(customer_code::bigint) from public.customers where customer_code ~ '^[0-9]+$'),294)), true);
commit;
